//! 🧾️ Direct dictionary values own literal scalar and ordered child relations.
use super::*;
use semio_framework_value::{DslValue,Number,FromValue,DecodedValue};
use store::sqlite_snapshot::transfer;
enum Attach<'a>{Entry(usize,&'a str),Array(i64,usize),Member(i64,usize,&'a str)}
struct Pending<'a>{value:&'a DslValue,attach:Attach<'a>}
fn decimal(value:u64,buffer:&mut[u8;20])->&str{let mut value=value;let mut start=20;loop{start-=1;buffer[start]=b'0'+(value%10)as u8;value/=10;if value==0{break}}std::str::from_utf8(&buffer[start..]).expect("decimal digits")}
pub(super) fn project(value:&FormDictionary,p:&mut Projection<'_,'_>)->Result<(),ValueError>{
 let mut identities=p.allocate_frontier(value.entries.len())?;for(index,entry)in value.entries.iter().enumerate(){identities.push((index,entry.question_id.as_str()));}p.sort_frontier(&mut identities,|a,b,control|{let order=transfer::compare_text(a.1,b.1,SqliteSnapshotPhase::ProjectSnapshot,control)?;if order.is_eq()&&a.0!=b.0{return Err(invalid("duplicate FormDictionary question identity"))}Ok(order)})?;p.insert_key("layout_form_dictionary",1,&[Cell::Integer(1)])?;let mut pending=p.allocate_frontier(value.entries.len())?;
 for(index,entry)in value.entries.iter().enumerate().rev(){pending.push(Pending{value:&entry.value,attach:Attach::Entry(index,&entry.question_id)});}
 while let Some(Pending{value,attach})=pending.pop(){let kind=match value{DslValue::Null=>"null",DslValue::Bool(_)=>"boolean",DslValue::Number(Number::UInt(_))=>"unsigned",DslValue::Number(Number::Int(_))=>"signed",DslValue::Number(Number::Float(_))=>"float",DslValue::String(_)=>"text",DslValue::Bytes(_)=>"bytes",DslValue::Array(_)=>"array",DslValue::Object(_)=>"object"};let id=p.insert("layout_dictionary_value",&[Cell::Text(kind)])?;
  match attach{Attach::Entry(index,name)=>{p.insert("layout_dictionary_entry",&[Cell::Integer(1),Cell::Integer(ordinal(index)?),Cell::Text(name),Cell::Integer(id)])?;},Attach::Array(parent,index)=>{p.insert("layout_dictionary_array",&[Cell::Integer(parent),Cell::Integer(ordinal(index)?),Cell::Integer(id)])?;},Attach::Member(parent,index,name)=>{p.insert("layout_dictionary_member",&[Cell::Integer(parent),Cell::Integer(ordinal(index)?),Cell::Text(name),Cell::Integer(id)])?;}}
  match value{DslValue::Null=>{},DslValue::Bool(value)=>{p.insert_key("layout_dictionary_boolean",id,&[Cell::Integer(i64::from(*value))])?;},DslValue::Number(Number::UInt(value))=>{let mut buffer=[0;20];p.insert_key("layout_dictionary_unsigned",id,&[Cell::Text(decimal(*value,&mut buffer))])?;},DslValue::Number(Number::Int(value))=>{p.insert_key("layout_dictionary_signed",id,&[Cell::Integer(*value)])?;},DslValue::Number(Number::Float(value))=>{let scalar=scalar64(p,*value)?;p.insert_key("layout_dictionary_float",id,&[Cell::Integer(scalar)])?;},DslValue::String(value)=>{p.insert_key("layout_dictionary_text",id,&[Cell::Text(value)])?;},DslValue::Bytes(value)=>{p.insert_key("layout_dictionary_bytes",id,&[Cell::Blob(value)])?;},DslValue::Array(values)=>for(index,value)in values.iter().enumerate().rev(){p.push_frontier(&mut pending,Pending{value,attach:Attach::Array(id,index)})?;},DslValue::Object(values)=>for(index,(name,value))in values.iter().enumerate().rev(){p.push_frontier(&mut pending,Pending{value,attach:Attach::Member(id,index,name)})?;}}
 }Ok(())
}
fn push<T>(values:&mut Vec<T>,value:T,control:&mut SqliteSnapshotControl<'_>)->Result<(),(ValueError,T)>{if values.len()==values.capacity(){let target=values.capacity().max(1).checked_mul(2);let Some(target)=target else{return Err((ValueError::new(ValueRefusalKind::OwnershipLimit,"dictionary frontier overflow"),value))};let bytes=target.checked_mul(size_of::<T>()).filter(|bytes|*bytes<=isize::MAX as usize);let Some(bytes)=bytes else{return Err((ValueError::new(ValueRefusalKind::OwnershipLimit,"dictionary frontier size overflow"),value))};if let Err(error)=control.admit_allocation_bytes(bytes){return Err((error,value))}if values.try_reserve_exact(target-values.len()).is_err(){return Err((ValueError::new(ValueRefusalKind::AllocationFailed,"dictionary frontier allocation failed"),value))}}values.push(value);Ok(())}
fn rows<'a>(r:&mut Reader<'a,'_,'_>,table:&'static str,parent:i64)->Result<Vec<&'a SqliteRow>,ValueError>{r.list(table,parent,1,2)}
enum Task<'a>{Value(i64),Array(usize),Object(Vec<&'a SqliteRow>)}
fn children(values:&mut Vec<DslValue>,count:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<DslValue>,ValueError>{let start=values.len().checked_sub(count).ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"dictionary frontier underflow"))?;let mut output=Vec::<DslValue>::guard_decoded(transfer::reserve(count,control)?);for index in start..values.len(){control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,index-start,count)?;output.get_mut().push(std::mem::replace(&mut values[index],DslValue::Null));}values.truncate(start);Ok(output.take())}
fn value(r:&mut Reader<'_,'_,'_>,id:i64)->Result<DslValue,ValueError>{let mut pending=transfer::reserve(1,r.control)?;pending.push(Task::Value(id));let mut values=Vec::<DslValue>::guard_decoded(Vec::new());while let Some(task)=pending.pop(){r.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,0)?;let output=match task{
 Task::Value(id)=>{let row=r.take("layout_dictionary_value",id)?;match row.text(1)?{
  "null"=>Some(DslValue::Null),"boolean"=>Some(DslValue::Bool(Reader::boolean(r.take("layout_dictionary_boolean",id)?,1)?)),
  "unsigned"=>{let row=r.take("layout_dictionary_unsigned",id)?;let text=row.text(1)?;if text.len()>20||text.is_empty()||(text.len()>1&&text.starts_with('0'))||!text.bytes().all(|byte|byte.is_ascii_digit()){return Err(invalid("dictionary canonical UInt64 magnitude"))}let value=text.parse::<u64>().map_err(|_|invalid("dictionary UInt64 range"))?;Some(DslValue::uint(value))},
  "signed"=>Some(DslValue::int(r.take("layout_dictionary_signed",id)?.integer(1)?)),"float"=>{let row=r.take("layout_dictionary_float",id)?;Some(DslValue::float(r.real(row,1)?))},"text"=>{let row=r.take("layout_dictionary_text",id)?;Some(DslValue::String(r.text(row,1)?))},"bytes"=>{let row=r.take("layout_dictionary_bytes",id)?;Some(DslValue::Bytes(Reconstruction::new(r.control)?.blob(row.blob(1)?)?))},
  "array"=>{let rows=rows(r,"layout_dictionary_array",id)?;push(&mut pending,Task::Array(rows.len()),r.control).map_err(|(error,_)|error)?;for row in rows.into_iter().rev(){push(&mut pending,Task::Value(row.integer(3)?),r.control).map_err(|(error,_)|error)?;}None},
  "object"=>{let rows=rows(r,"layout_dictionary_member",id)?;for row in &rows{row.text(3)?;}let count=rows.len();let slot=pending.len();push(&mut pending,Task::Object(rows),r.control).map_err(|(error,_)|error)?;for index in(0..count).rev(){let Task::Object(rows)=&pending[slot]else{unreachable!()};let child=rows[index].integer(4)?;push(&mut pending,Task::Value(child),r.control).map_err(|(error,_)|error)?;}None},
  _=>return Err(invalid("dictionary intrinsic kind"))}},
 Task::Array(count)=>Some(DslValue::Array(children(values.get_mut(),count,r.control)?)),Task::Object(rows)=>{let mut children=Vec::<DslValue>::guard_decoded(children(values.get_mut(),rows.len(),r.control)?);let mut output=DecodedValue::new(transfer::reserve(rows.len(),r.control)?,|values:Vec<(String,DslValue)>|{for(_,value)in values{<DslValue as FromValue>::retire_decoded(value)}});for(index,row)in rows.iter().enumerate(){let name=r.text(row,3)?;let value=std::mem::replace(&mut children.get_mut()[index],DslValue::Null);output.get_mut().push((name,value));}Some(DslValue::Object(output.take()))}};
 if let Some(value)=output{if let Err((error,value))=push(values.get_mut(),value,r.control){<DslValue as FromValue>::retire_decoded(value);return Err(error)}}}values.get_mut().pop().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"dictionary empty value frontier"))}
pub(super) fn reconstruct(r:&mut Reader<'_,'_,'_>)->Result<FormDictionary,ValueError>{let row=r.take("layout_form_dictionary",1)?;if row.integer(1)?!=1{return Err(invalid("dictionary document identity"))}let source=rows(r,"layout_dictionary_entry",1)?;let mut owner=DecodedValue::new(FormDictionary{entries:transfer::reserve(source.len(),r.control)?},<FormDictionary as FromValue>::retire_decoded);for row in source{let question_id=r.text(row,3)?;let value=value(r,row.integer(4)?)?;owner.get_mut().entries.push(FormDictionaryEntry{question_id,value});}let result=r.control.allocation_stage(SqliteSnapshotPhase::ReconstructSnapshot,|allowance,progress|{let mut callback=|event:semio_framework_value::native_decoding::NativeDecodeProgress|progress(event.completed,event.total);let mut native=semio_framework_value::NativeDecodeControl::new(allowance,&mut callback);let result=owner.get().validate_controlled(&mut native);(result,native.owned_bytes())})??;let _=result;Ok(owner.take())}
